INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱允炆", "aliases": ["明惠帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明惠帝。洪武31年（年号对照1398年），本表记录了朱允炆的活动。", "biography": null, "status": "draft", "id": "76ea9485-acac-508c-a6ae-e2532462c03e"}, {"name": "朱标", "aliases": ["朱標"], "era": "明", "birth_year": null, "death_year": null, "description": "明太祖时的皇太子。本纪记其于洪武二十五年去世。", "biography": null, "status": "draft", "id": "5c5e855f-d901-54a9-80ba-9dfe24f7c9f9"}, {"name": "暴昭", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武31年（年号对照1398年）五月，暴昭出任刑部尚书。", "biography": null, "status": "draft", "id": "0f8b3c80-cc83-55a0-99cc-45fce1f20642"}, {"name": "夏原吉", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，夏原吉出任户部尚书。", "biography": null, "status": "draft", "id": "1f881ca5-40e5-5578-8f0a-653eb82f0a44"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "郭资", "aliases": ["郭資"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）十一月，郭资出任户部尚书，继续主持北平布政事务。", "biography": null, "status": "draft", "id": "953a02cf-d4ed-5d6a-9e65-8716d5b78f3a"}, {"name": "耿炳文", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年随朱元璋于和州。", "biography": null, "status": "draft", "id": "348f31d6-f709-5dde-a5f7-f84796bfa663"}, {"name": "李景隆", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "曹国公。本纪记其在建文元年继耿炳文后为征虏大将军。", "biography": null, "status": "draft", "id": "74bfbb9a-13ef-5b0a-8ce8-2e9f902907af"}, {"name": "齐泰", "aliases": ["齊泰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武31年（年号对照1398年）五月，齐泰出任兵部尚书，参与处理国家政务。", "biography": null, "status": "draft", "id": "6ffd1a4d-05e3-5c22-a9b8-c44a7ea23c0e"}, {"name": "雒佥", "aliases": ["雒僉"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）十二月，雒佥出任刑部尚书，仍兼任保定知府。", "biography": null, "status": "draft", "id": "e0a8a498-4f6e-52f8-9202-18b5aec73ade"}, {"name": "胡广（明代内阁大学士）", "aliases": ["胡廣"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，胡广以翰林侍讲身份入直文渊阁。", "biography": null, "status": "draft", "id": "c9d78e04-f4b5-58bb-9869-c02bda75f0d3"}, {"name": "铁铉", "aliases": ["鐵鉉"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文2年（年号对照1400年）十二月，铁铉获任兵部尚书，督理军务。", "biography": null, "status": "draft", "id": "c762b1dc-9ad1-5d54-95f1-1a34c8da3202"}, {"name": "盛庸", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪记其为都督，参与守卫济南。", "biography": null, "status": "draft", "id": "30198cca-1b25-5099-9bd8-021538a90b39"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱允炆追尊生父与常氏", "description": "朱允炆追尊其父朱标为孝康皇帝，庙号兴宗，追尊常氏为孝康皇后。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "61a5b567-f0e9-5512-a291-36d91dac0efd"}, {"title": "朱允炆尊吕氏为皇太后并册立马氏", "description": "朱允炆尊生母吕氏为皇太后，册立妃马氏为皇后。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "305f831a-ab91-5c5b-a2fb-5c0e5f6cd712"}, {"title": "朱允炆封三名弟弟为王并册立皇太子", "description": "朱允炆封弟弟朱允熥为吴王、朱允熞为衡王、朱允熙为徐王，立长子朱文奎为皇太子。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0a1edc39-1e50-57a7-8c66-66027a1dbae1"}, {"title": "明廷下诏访贤并救助老人等民众", "description": "朝廷下诏访求尚未任用的贤才，赐老人米、肉和绵帛，命官府照养无依靠或有残疾的人。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9708ee54-47ff-5b76-9d7c-12e4decc5b14"}, {"title": "明廷下诏推行劝农兴学和救灾等政务", "description": "朝廷下诏重视农桑、兴办学校、考察官吏、赈济灾民、褒扬节孝、掩埋暴露遗骨、免征荒田田租。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f58eb42-12c5-554b-b199-06821dea2071"}, {"title": "明廷重新规定军户、王府权力和官制", "description": "本纪记载，卫所军户已经绝户的予以除籍，不再勾补。朝廷禁止藩王节制文武吏士，并重新规定中央和地方官制。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b48b54a0-6d08-52e0-9958-8491030e975d"}, {"title": "明廷举行祭孔礼并暂停各官署非急事务", "description": "明廷举行释奠礼祭祀孔子，并暂停各官署不紧急的事务。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4cfe02c-9d60-55db-8dbb-3ce4dd168cb5"}, {"title": "明廷在开平等地部署军队", "description": "都督宋忠、徐凯和耿瓛率军分别驻屯开平、临清、山海关。朝廷另调北平和永清两卫的军队到彰德、顺德。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87837928-10a7-5f07-ae80-e193e8849c13"}, {"title": "明廷派暴昭夏原吉等分巡各地", "description": "朝廷派暴昭、夏原吉等二十四人担任采访使，分巡各地。卷末校记说明，暴昭当时的官衔据其他记载为刑部尚书。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfdba3bb-3163-543d-b1b4-fd3cdb8604dc"}, {"title": "京师地震，明廷征求直言", "description": "京师发生地震，朝廷下令征求直言。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年三月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8ef925a1-1120-59cd-b6af-bf349bea254a"}, {"title": "湘王朱柏自焚身亡", "description": "本纪记载，湘王朱柏在四月自焚身亡。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "194d28a0-aa39-5acb-9128-a7ff040342ca"}, {"title": "齐王和代王获罪被废为庶人", "description": "齐王朱榑和代王朱桂获罪，被废为庶人。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "248c8cda-7ec0-5bcc-9bd9-a0cd26739a74"}, {"title": "明廷遣燕王世子朱高炽等回北平", "description": "朝廷遣燕王世子朱高炽及其两个弟弟朱高煦、朱高燧返回北平。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fbe43fbb-2464-5c0c-a9e0-b0ced7ad726f"}, {"title": "岷王朱楩获罪，被废为庶人并迁漳州", "description": "岷王朱楩获罪，被废为庶人并迁往漳州。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23005df8-546d-5345-8aae-d431f8153bcf"}, {"title": "倪谅上报变故，燕旗校于谅等被处死", "description": "燕山护卫百户倪谅上报变故，燕王府旗校于谅等被处死。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年六月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "440088a2-8ac9-588e-bc38-679eeb5379ae"}, {"title": "朝廷责备燕王，张信归附燕王", "description": "朝廷下诏责备燕王朱棣，逮捕燕王府官员。北平都指挥张信转而归附燕王。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6af09465-b74a-5405-9644-963a847328e0"}, {"title": "燕王朱棣起兵，张昺和谢贵被杀", "description": "本纪记载，七月癸酉燕王朱棣举兵反明廷，布政使张昺与都司谢贵被杀。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6f782c37-bbaf-54bf-865c-76e1296fb768"}, {"title": "葛诚等遇难，郭资等归附燕军", "description": "燕王起兵后，长史葛诚、指挥卢振、教授余逢辰因而身亡，参政郭资、副使墨麟、佥事吕震等归降燕军。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f975321b-e91d-5040-a4f0-02395b38e841"}, {"title": "燕军起兵后北平一带官军退守", "description": "指挥马宣退往蓟州，俞瑱退往居庸。宋忠赶赴北平，得知变故后退守怀来。通州、遵化和密云相继归附燕军。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f940c316-65fc-5c3f-88d9-cd1d2b59f57a"}, {"title": "燕军攻下蓟州，马宣战死", "description": "燕军攻下蓟州，马宣在战事中阵亡。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd94dceb-3923-5097-84ed-ef3441a5f11f"}, {"title": "燕军攻下居庸关", "description": "燕军于七月己卯攻占居庸关。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5d999860-cf3c-5622-a33e-4b1ea47bd314"}, {"title": "燕军攻下怀来，宋忠等身亡", "description": "燕军攻下怀来，宋忠与俞瑱被俘后身亡，彭聚与孙泰战死。永平指挥郭亮等归附燕军。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd44a270-0fdc-5fbe-ab1d-baa428c67572"}, {"title": "谷王朱橞自宣府奔赴京师", "description": "本纪记载，谷王朱橞从宣府奔赴京师。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05530ea9-585f-530a-81e7-275f2bfd33bb"}, {"title": "明廷命耿炳文等率军征讨燕王", "description": "朝廷命长兴侯耿炳文为征虏大将军，驸马都尉李坚和都督甯忠为左右副将军，率军讨伐燕王。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5c19900-1aeb-5eab-b199-92daa9b44dbe"}, {"title": "明廷祭告天地并将燕王除出宗籍", "description": "朝廷告祭天地、宗庙和社稷，并将燕王从宗室属籍中除名。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e3c60730-bf21-5b3e-84c6-1d898bdc8369"}, {"title": "朱允炆发布讨燕诏令", "description": "朱允炆发布讨燕诏令，在诏书中陈述朝廷对燕王及相关藩王的指控，动员中央、地方和军中人员支援征讨。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "af3eae1c-fa06-5733-9ddd-a960e51cf87d"}, {"title": "明廷命吴杰等分路讨燕", "description": "朝廷随即命吴杰、吴高、耿瓛、盛庸、潘忠、杨松、顾成、徐凯、李友、陈晖、平安等分路进军。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32c96e08-3715-52df-9826-fd85ef380cc5"}, {"title": "明廷在真定设置平燕布政使司", "description": "朝廷在真定设置平燕布政使司，由尚书暴昭主管司事。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f5071be0-d9af-5399-9322-de65cccc597e"}, {"title": "明军进驻真定河间和鄚州", "description": "耿炳文率部到真定，徐凯驻河间，潘忠和杨松驻鄚州。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年八月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78987151-7af0-5ae3-b077-ea5f6cafa521"}, {"title": "燕军攻下雄县，潘忠和杨松在月漾桥被俘", "description": "燕军攻下雄县。潘忠和杨松在月漾桥交战后被俘，鄚州也失守。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年八月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c6db34be-1557-5c7d-a9d2-34922fe89676"}, {"title": "耿炳文在滹沱河北战败后退守真定", "description": "耿炳文与燕军在滹沱河北岸交战失利，李坚、甯忠和顾成被俘。耿炳文退守真定，燕军进攻未能破城，随后撤走。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年八月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84637b58-d6ed-5727-babf-6915e83b47e7"}, {"title": "明廷召辽王宁王返京并削宁王护卫", "description": "朝廷召辽王朱植与宁王朱权返回京师。宁王未到，朝廷下诏削去其护卫。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0875e5f3-322c-5ae5-b71a-3d66717597b8"}, {"title": "李景隆接替耿炳文任征虏大将军", "description": "朝廷任命曹国公李景隆为征虏大将军，接替耿炳文。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年八月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e970819-caa0-523e-b3ae-e08fd7317fcf"}, {"title": "吴高等率辽东兵围攻永平", "description": "吴高、耿瓛和杨文率辽东军队围攻永平。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年九月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1595ab7-7201-5ce8-adb0-56a64865fdb5"}, {"title": "燕军增援永平，吴高退守山海关", "description": "李景隆率部到达河间。燕军援救永平，吴高退守山海关。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年九月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1573e34-f13d-5a20-bb21-6f0decfd75d7"}, {"title": "燕军攻占大宁并带宁王及朵颜三卫军士返北平", "description": "燕军由刘家口小路进据大宁，守将朱鉴死于此役。刘真、陈亨率兵救援，陈亨转而归附燕军。燕军带宁王朱权和朵颜三卫的军士返回北平。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "66f520c1-67b5-5c84-bffa-ff51a8c55be6"}, {"title": "李景隆围攻北平，燕军回援", "description": "李景隆率部围攻北平，燕军返回救援。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年十月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58a4e28e-a087-5583-acaf-64ca0ccc71f8"}, {"title": "李景隆在郑村坝战败后退往德州", "description": "李景隆在郑村坝与燕军作战失利，退往德州，所部溃散。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年十一月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "54f7c30b-58b0-5b1a-b972-379c86a6da17"}, {"title": "燕王朱棣再次向朝廷上书", "description": "燕王朱棣再次向朝廷递交书信。 按原历纪年，事情发生在公元1399至1400年之间。", "start_year": null, "end_year": null, "time_original": "建文元年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1be1aaaa-6e36-5407-9c55-782ac5915eae"}, {"title": "齐泰被罢免", "description": "建文元年（年号对照1399年）十一月，齐泰被罢免。原历日期只能确定在公元1399年至1400年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "建文元年（年号对照1399年）十一月；发生于公元1399至1400年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "a2520674-6c1b-57b0-b118-e4e057839a2d"}, {"title": "朱允炆命入朝官员免行贺礼", "description": "正月初一，朱允炆下诏各地入朝的官员免行贺礼。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年正月丙寅朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6705960b-c0f4-572b-b2f6-ebdfcebb1c19"}, {"title": "明廷举行祭孔典礼", "description": "明廷在正月丁卯举行释奠礼祭祀孔子。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年正月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dfc64c41-e72f-5a58-8cea-9df780584493"}, {"title": "燕军由蔚州进攻大同，李景隆率军赴援", "description": "燕军攻下蔚州后进攻大同。李景隆从德州率军增援，燕军撤回北平。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9ce71773-abff-5e1d-94e6-caec1072b757"}, {"title": "保定知府雒佥归附燕军", "description": "本纪记载，保定知府雒佥转而归附燕军。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "97f5d3ce-deee-54d6-87a9-dcf258fbeeaf"}, {"title": "明廷再次将都察院改为御史府", "description": "朝廷再次将都察院改为御史府。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年二月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9630da0b-9c16-5ed4-bf48-a013879a8ab7"}, {"title": "明廷下诏减轻江浙田赋", "description": "朱允炆以江浙田赋过重为由下诏减免，规定每亩税额不得超过一斗，并准苏州、松江人继续在户部任官。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a7c2e88b-aef0-5ad6-b984-f7ee0fbdc377"}, {"title": "本纪记三月初一日食", "description": "本纪记载，三月初一出现日食。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年三月丙寅朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e311ca1a-46bf-548a-b47c-494bd7e9fa96"}, {"title": "明廷赐胡广等进士及第或出身", "description": "朝廷分别赐胡广等人进士及第或出身。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c462eb5c-4d31-5e39-912e-005bb538bd4d"}, {"title": "李景隆在白沟河首次交战击败燕军", "description": "李景隆与燕军在白沟河交战，朝廷军队此日获胜。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年四月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2accd96e-c3cb-506f-9442-61458ba45ab1"}, {"title": "白沟河再战李景隆败退", "description": "次日双方再战，李景隆军失利，都督瞿能、越巂侯俞渊、指挥滕聚等阵亡，李景隆奔往德州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年四月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7225511e-6045-5978-a464-763fb146ac35"}, {"title": "李景隆退往济南，燕军攻占德州", "description": "李景隆退往济南。燕军攻占德州，继续进攻济南。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年五月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dc19184a-4150-58c6-840c-3f5b07b28e0d"}, {"title": "李景隆在济南城下败退，铁铉与盛庸守城", "description": "李景隆在济南城下战败后南撤。参政铁铉与都督盛庸竭力抵御燕军。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年五月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2bb0f955-fa59-54e7-a942-318192365828"}, {"title": "明廷派李得成向燕军传令停兵", "description": "朝廷派尚宝丞李得成向燕军传达停兵要求。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年六月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eba3ee90-6f07-5c4b-86aa-ccf5f8a8797e"}, {"title": "承天门起火，明廷诏求直言", "description": "承天门发生火灾，朝廷下诏征求直言。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年八月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5249485a-0df5-58b1-9652-216c9ec6a7ab"}, {"title": "盛庸铁铉击败燕军，济南解围", "description": "盛庸与铁铉击败燕军，济南解围，朝廷军队收复德州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年八月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77e9ba24-6906-5350-b018-aaa7fdaf9ddf"}, {"title": "明廷下诏录用洪武年间被废功臣的后人", "description": "朝廷下诏，将洪武年间因罪被废的功臣后人收入录用范围。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "282bbab1-9a78-5b7d-bf2b-c164c9a4ffc8"}, {"title": "盛庸被封历城侯，铁铉获擢山东布政使", "description": "朝廷封盛庸为历城侯，提拔铁铉为山东布政使，使他参赞军务。本纪继而记铁铉不久后升任兵部尚书。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年九月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf84e320-d8b9-50f2-9659-bde505448a4e"}, {"title": "盛庸任平燕将军，官军分屯德州等地", "description": "朝廷任命盛庸为平燕将军，陈晖和平安为副将。盛庸屯驻德州，平安和吴杰屯驻定州，徐凯屯驻沧州。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e7e96362-1c95-5315-a429-0ca10919706e"}, {"title": "朝廷召李景隆返回并免其死罪", "description": "朝廷在十月召回李景隆，对他赦免不杀。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ef74cee8-d800-5d75-b5bd-8778da238dc6"}, {"title": "燕军袭击沧州并俘获徐凯", "description": "燕军袭击沧州，徐凯被俘。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78851b24-29a4-5beb-9f54-d5145fd6ea88"}, {"title": "燕军进犯济宁并逼近东昌", "description": "燕军进犯济宁，随后逼近东昌。", "start_year": 1400, "end_year": 1400, "time_original": "建文二年十二月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09ab2bc7-5e1e-5a8a-8c1b-20fc26d3a0a4"}, {"title": "盛庸在东昌击败燕军，张玉阵亡", "description": "盛庸率军击败燕军，燕军将领张玉在此役被杀。", "start_year": 1401, "end_year": 1401, "time_original": "建文二年十二月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd72bba0-e456-56ce-bdb8-4f4e839d20ee"}, {"title": "盛庸再胜并命各部合击燕军", "description": "双方次日再次交战，盛庸又胜，燕军退往馆陶。盛庸命驻屯各处的部队合击，切断燕军退路。", "start_year": 1401, "end_year": 1401, "time_original": "建文二年十二月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf714451-ee23-5d8e-846c-b0cd1389d642"}]'::jsonb)
